-- 0032_dashboard_system_seed.sql seeded "rapports-application"'s four panels
-- pointing at architecture-neo4j (Cypher). Following
-- 0034_demonstration_datasources_postgres.sql,
-- 0035_motivation_datasource_postgres.sql and
-- 0036_principles_datasource_postgres.sql's precedent, this backfill points
-- the dashboard's latest revision (2) at the native Postgres datasource.
--
-- "acteurs-metier" and "fonctions-metier" are fixed 1..2-hop and 1-hop
-- traversals (no recursion needed, unlike "motivation"'s 1..5-hop chain).
-- "composants-technologiques" and "traceabilite-exigences" both resolve the
-- source model's convention of tagging a Technology-layer element as
-- belonging to an application via an "Application" element property whose
-- value equals the application's name — translated as a join through
-- element_properties/property_definitions (packages/db/src/schema.ts),
-- scoped to the *technology element's own* workspace (property_def_uuid is
-- workspace-scoped), not the application's. "composants-technologiques"
-- additionally reproduces the source's ad hoc rankGroups layout hints (a
-- root CommunicationNetwork with no parent CommunicationNetwork gets
-- "subnet", a TechnologyInterface gets "private-endpoint") as an EXISTS
-- check over Composition/Aggregation relationships.
--
-- Every panel here also relies on the ArchiMate layer classification Neo4j
-- nodes get at export time (packages/db-neo4j/src/layer.ts's getLayer);
-- Postgres has no equivalent stored column, so the same classification is
-- inlined as a CASE expression per query — it must be kept in sync with
-- getLayer if that function's rules ever change.
UPDATE "dashboard_revisions" AS dr
SET "definition" = $def$
{"id": "rapports-application", "title": "Rapports application", "description": "Acteurs métier, fonctions, technologies et exigences d’une application.", "category": "Applications", "schemaVersion": 2, "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["ApplicationComponent"]}}], "panels": [{"id": "acteurs-metier", "panel": {"title": "Acteurs métier (voisinage applicatif)", "description": "Acteurs et rôles métier atteints depuis un composant applicatif donné, jusqu'à 2 sauts.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Identifiant de l'application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(array_agg(node_id), ARRAY[]::text[]) AS \"nodeIds\"\nFROM (\n  SELECT node_id FROM (\n    SELECT ne.uuid AS node_id\n    FROM elements app\n    JOIN workspaces aw ON aw.id = app.workspace_id\n    JOIN relationships r1 ON r1.source_uuid = app.uuid OR r1.target_uuid = app.uuid\n    JOIN workspaces r1w ON r1w.id = r1.workspace_id\n    JOIN elements ne ON ne.uuid = CASE WHEN r1.source_uuid = app.uuid THEN r1.target_uuid ELSE r1.source_uuid END\n    JOIN workspaces new ON new.id = ne.workspace_id\n    WHERE aw.organization_id = $organizationId AND app.uuid = $appId AND app.type = 'ApplicationComponent'\n      AND r1w.organization_id = $organizationId AND new.organization_id = $organizationId\n      AND r1.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association')\n      AND ne.type IN ('BusinessActor', 'BusinessRole')\n\n    UNION\n\n    SELECT ne2.uuid AS node_id\n    FROM elements app\n    JOIN workspaces aw ON aw.id = app.workspace_id\n    JOIN relationships r1 ON r1.source_uuid = app.uuid OR r1.target_uuid = app.uuid\n    JOIN workspaces r1w ON r1w.id = r1.workspace_id\n    JOIN elements mid ON mid.uuid = CASE WHEN r1.source_uuid = app.uuid THEN r1.target_uuid ELSE r1.source_uuid END\n    JOIN workspaces midw ON midw.id = mid.workspace_id\n    JOIN relationships r2 ON r2.source_uuid = mid.uuid OR r2.target_uuid = mid.uuid\n    JOIN workspaces r2w ON r2w.id = r2.workspace_id\n    JOIN elements ne2 ON ne2.uuid = CASE WHEN r2.source_uuid = mid.uuid THEN r2.target_uuid ELSE r2.source_uuid END\n    JOIN workspaces ne2w ON ne2w.id = ne2.workspace_id\n    WHERE aw.organization_id = $organizationId AND app.uuid = $appId AND app.type = 'ApplicationComponent'\n      AND r1w.organization_id = $organizationId AND midw.organization_id = $organizationId\n      AND r2w.organization_id = $organizationId AND ne2w.organization_id = $organizationId\n      AND r1.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association') AND r2.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association')\n      AND ne2.type IN ('BusinessActor', 'BusinessRole')\n  ) hops\n  LIMIT 500\n) capped"}}, "layout": {"x": 0, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "fonctions-metier", "panel": {"title": "Fonctions métier", "description": "Composants applicatifs directement liés à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT\n  (\n    SELECT array_agg(DISTINCT node_id) FROM (\n      SELECT app.uuid AS node_id\n      UNION\n      SELECT ne.uuid AS node_id\n      FROM relationships r\n      JOIN workspaces rw ON rw.id = r.workspace_id\n      JOIN elements ne ON ne.uuid = CASE WHEN r.source_uuid = app.uuid THEN r.target_uuid ELSE r.source_uuid END\n      JOIN workspaces new ON new.id = ne.workspace_id\n      WHERE (r.source_uuid = app.uuid OR r.target_uuid = app.uuid)\n        AND rw.organization_id = $organizationId AND new.organization_id = $organizationId\n        AND r.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association')\n        AND ne.type = 'ApplicationComponent'\n    ) x\n  ) AS \"nodeIds\",\n  app.uuid AS \"emphasizedId\"\nFROM elements app\nJOIN workspaces aw ON aw.id = app.workspace_id\nWHERE aw.organization_id = $organizationId AND app.uuid = $appId AND app.type = 'ApplicationComponent'"}}, "layout": {"x": 6, "y": 0, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "composants-technologiques", "panel": {"title": "Composants technologiques", "description": "Éléments technologiques documentés comme appartenant à l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT \"nodeIds\", \"rankGroups\"\nFROM (\n  WITH techs AS (\n    SELECT DISTINCT t.uuid AS node_id, t.type AS node_type\n    FROM elements app\n    JOIN workspaces aw ON aw.id = app.workspace_id\n    CROSS JOIN elements t\n    JOIN workspaces tw ON tw.id = t.workspace_id\n    JOIN element_properties ep ON ep.element_id = t.id\n    JOIN property_definitions pd ON pd.uuid = ep.property_def_uuid AND pd.workspace_id = t.workspace_id\n    WHERE aw.organization_id = $organizationId AND app.uuid = $appId AND app.type = 'ApplicationComponent'\n      AND tw.organization_id = $organizationId\n      AND (CASE\n    WHEN t.type LIKE 'Business%' OR t.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN t.type LIKE 'Application%' OR t.type = 'DataObject' THEN 'Application'\n    WHEN t.type LIKE 'Technology%' OR t.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN t.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN t.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN t.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN t.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END) = 'Technology'\n      AND pd.name = 'Application'\n      AND ep.value = app.name\n  )\n  SELECT\n    COALESCE((SELECT array_agg(node_id) FROM techs), ARRAY[]::text[]) AS \"nodeIds\",\n    COALESCE((\n      SELECT jsonb_agg(jsonb_build_object('id', node_id, 'rankGroup', rank_group))\n      FROM (\n        SELECT node_id, 'subnet' AS rank_group\n        FROM techs t\n        WHERE t.node_type = 'CommunicationNetwork'\n          AND NOT EXISTS (\n            SELECT 1 FROM relationships r\n            JOIN workspaces rw ON rw.id = r.workspace_id\n            JOIN elements parent ON parent.uuid = r.target_uuid\n            JOIN workspaces pw ON pw.id = parent.workspace_id\n            WHERE r.source_uuid = t.node_id\n              AND rw.organization_id = $organizationId AND pw.organization_id = $organizationId\n              AND r.type IN ('Composition', 'Aggregation')\n              AND parent.type = 'CommunicationNetwork'\n          )\n        UNION ALL\n        SELECT node_id, 'private-endpoint' AS rank_group\n        FROM techs t\n        WHERE t.node_type = 'TechnologyInterface'\n      ) rg\n    ), '[]'::jsonb) AS \"rankGroups\"\n) AS reachable"}}, "layout": {"x": 0, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}, {"id": "traceabilite-exigences", "panel": {"title": "Traçabilité des exigences", "description": "Exigences réalisées par les composants technologiques de l’application sélectionnée.", "resultType": "graph", "parameters": [{"name": "appId", "label": "Application", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(array_agg(DISTINCT node_id), ARRAY[]::text[]) AS \"nodeIds\"\nFROM (\n  WITH qualifying_techs AS (\n    SELECT DISTINCT t.uuid AS node_id\n    FROM elements app\n    JOIN workspaces aw ON aw.id = app.workspace_id\n    CROSS JOIN elements t\n    JOIN workspaces tw ON tw.id = t.workspace_id\n    JOIN element_properties ep ON ep.element_id = t.id\n    JOIN property_definitions pd ON pd.uuid = ep.property_def_uuid AND pd.workspace_id = t.workspace_id\n    WHERE aw.organization_id = $organizationId AND app.uuid = $appId AND app.type = 'ApplicationComponent'\n      AND tw.organization_id = $organizationId\n      AND (CASE\n    WHEN t.type LIKE 'Business%' OR t.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN t.type LIKE 'Application%' OR t.type = 'DataObject' THEN 'Application'\n    WHEN t.type LIKE 'Technology%' OR t.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN t.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN t.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN t.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN t.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END) = 'Technology'\n      AND pd.name = 'Application'\n      AND ep.value = app.name\n      AND EXISTS (\n        SELECT 1 FROM relationships r\n        JOIN workspaces rw ON rw.id = r.workspace_id\n        JOIN elements req ON req.uuid = r.target_uuid\n        JOIN workspaces reqw ON reqw.id = req.workspace_id\n        WHERE r.source_uuid = t.uuid\n          AND rw.organization_id = $organizationId AND reqw.organization_id = $organizationId\n          AND r.type = 'Realization' AND req.type = 'Requirement'\n      )\n  ),\n  realized_requirements AS (\n    SELECT DISTINCT req.uuid AS node_id\n    FROM qualifying_techs qt\n    JOIN relationships r ON r.source_uuid = qt.node_id\n    JOIN workspaces rw ON rw.id = r.workspace_id\n    JOIN elements req ON req.uuid = r.target_uuid\n    JOIN workspaces reqw ON reqw.id = req.workspace_id\n    WHERE rw.organization_id = $organizationId AND reqw.organization_id = $organizationId\n      AND r.type = 'Realization' AND req.type = 'Requirement'\n  )\n  SELECT node_id FROM qualifying_techs\n  UNION\n  SELECT node_id FROM realized_requirements\n) all_nodes"}}, "layout": {"x": 6, "y": 7, "width": 6, "height": 7}, "parameterBindings": {"appId": {"source": "dashboard", "parameter": "appId"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-17T03:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "system"}
$def$::jsonb
FROM "dashboards" AS dd
WHERE dr."dashboard_id" = dd."id"
  AND dd."dashboard_id" = 'rapports-application'
  AND dd."workspace_id" IS NULL
  AND dr."revision" = dd."latest_revision";
